"""
verify_geometry.py  —  字母表示数动画 几何/公式 验证脚本
本动画以代数公式为主，无复杂几何，重点验证：
  1. grep_MathTex  — 确保 MathTex 里无中文
  2. verify_boundaries — 元素位置在安全帧内
  3. verify_angles — 本动画无角度元素，跳过
"""
import re
import numpy as np

SAFE_X = (-4.0, 4.0)
SAFE_Y = (-7.5, 7.5)


def grep_MathTex(source_code: str) -> list:
    CHINESE_RE = re.compile(r'[\u4e00-\u9fff\u3400-\u4dbf\uff00-\uffef]')
    MATHTEX_RE = re.compile(r'MathTex\s*\(([^)]+)\)')
    violations = []
    for lineno, line in enumerate(source_code.splitlines(), start=1):
        for match in MATHTEX_RE.finditer(line):
            inner = match.group(1)
            chinese_chars = CHINESE_RE.findall(inner)
            if chinese_chars:
                violations.append(
                    f"  Line {lineno}: MathTex 含中文 {chinese_chars!r}  -> {line.strip()[:80]}"
                )
    return violations


def verify_boundaries(positions: dict) -> list:
    warnings = []
    for name, pos in positions.items():
        x, y = pos[0], pos[1]
        if not (SAFE_X[0] <= x <= SAFE_X[1]):
            warnings.append(f"  WARNING {name}: x={x:.2f} out of [{SAFE_X[0]}, {SAFE_X[1]}]")
        if not (SAFE_Y[0] <= y <= SAFE_Y[1]):
            warnings.append(f"  WARNING {name}: y={y:.2f} out of [{SAFE_Y[0]}, {SAFE_Y[1]}]")
    return warnings


def verify_angles(angles_deg: dict) -> list:
    warnings = []
    for name, deg in angles_deg.items():
        if deg > 180:
            warnings.append(f"  WARNING {name}: {deg:.1f}deg > 180, likely wrong direction!")
        elif deg > 90:
            warnings.append(f"  INFO {name}: {deg:.1f}deg > 90, check direction")
    return warnings


if __name__ == "__main__":
    import os

    source_path = "letter_represents_number.py"
    if not os.path.exists(source_path):
        print(f"[SKIP] {source_path} not yet generated, skipping file-level checks")
        source_code = ""
    else:
        with open(source_path, "r", encoding="utf-8") as f:
            source_code = f.read()

    print("=" * 60)
    print("Manim Animation Verification: Yong Zimu Biaoshi Shu")
    print("=" * 60)

    print("\n[1] MathTex Chinese character check")
    violations = grep_MathTex(source_code)
    if violations:
        print("  FAIL:")
        for v in violations:
            print(v)
    else:
        print("  PASS: No Chinese in MathTex")

    print("\n[2] Key element boundary check")
    key_positions = {
        "author_info":      np.array([0.0,  7.0, 0]),
        "hook_title":       np.array([0.0,  5.5, 0]),
        "scene_title":      np.array([0.0,  5.5, 0]),
        "formula_S_ab":     np.array([0.0,  1.5, 0]),
        "rectangle_center": np.array([0.0,  0.5, 0]),
        "label_a":          np.array([-2.5, 0.5, 0]),
        "label_b":          np.array([0.0,  2.3, 0]),
        "rule_card_1":      np.array([0.0,  2.0, 0]),
        "rule_card_2":      np.array([0.0,  0.0, 0]),
        "rule_card_3":      np.array([0.0, -2.0, 0]),
        "bottom_explain":   np.array([0.0, -5.0, 0]),
        "outro_author":     np.array([0.0,  1.5, 0]),
        "outro_follow":     np.array([0.0, -0.5, 0]),
    }
    boundary_warns = verify_boundaries(key_positions)
    if boundary_warns:
        for w in boundary_warns:
            print(w)
    else:
        print("  PASS: All positions within safe bounds")

    print("\n[3] Angle check (none in this animation)")
    angles = {}
    angle_warns = verify_angles(angles)
    if angle_warns:
        for w in angle_warns:
            print(w)
    else:
        print("  PASS: No angle elements")

    print("\n" + "=" * 60)
    total_issues = len(violations) + len(boundary_warns) + len(angle_warns)
    if total_issues == 0:
        print("ALL CHECKS PASSED - Ready to render!")
    else:
        print(f"WARNING: {total_issues} issue(s) need fixing before render.")
    print("=" * 60)
